export function makeRule(){return {id:uid(),name:'New interaction',enabled:true,trigger:'interact',selfTag:'',otherTag:'',conditionTag:'',tagMode:'present',condition:'always',conditionTarget:'self',stat:'',material:'@self',op:'>=',threshold:0,target:'other',effect:'stat',effectStat:'',amount:5,tag:'',signal:'',signalStat:''};}
